#!/bin/sh
# Generate the gh:#1414 fix insert/stream decks in.stream_ol, in.stream_noch,
# in.stream_allin beside this script. Same D/d = 6 container as in.pebble_bed;
# insertion face stream_face.stl (0.04 m square, z = 0.15, two triangles).
# Frames are written with `run N pre no`, one continuous run.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
cd "$here"
gen() {
name=$1
cat > in.$name <<EOF
# gh:#1414 insert/stream cross-code deck (generated by make_stream_decks.sh; see
# crates/outram-park-fork-liggghts/verification_and_validation/insertion/README.md).
atom_style	granular
atom_modify	map array
boundary	f f f
newton		off
communicate	single vel yes
units		si
region		reg block -0.035 0.035 -0.035 0.035 -0.005 0.35 units box
create_box	1 reg
neighbor	0.003 bin
neigh_modify	delay 0
fix 		m1 all property/global youngsModulus peratomtype 5.0e6
fix 		m2 all property/global poissonsRatio peratomtype 0.3
fix 		m3 all property/global coefficientRestitution peratomtypepair 1 0.5
fix 		m4 all property/global coefficientFriction peratomtypepair 1 0.3
pair_style	gran model hertz tangential history
pair_coeff	* *
timestep	5e-6
fix		cyl all wall/gran model hertz tangential history primitive type 1 zcylinder 0.030 0. 0.
fix		zwall all wall/gran model hertz tangential history primitive type 1 zplane 0.0
fix		face all ${FACESTYLE:-mesh/surface} file stream_face.stl type 1
fix		pts all particletemplate/sphere 15485863 atom_type 1 density constant 2500 radius constant 0.003
fix		pdd all particledistribution/discrete 15485867 1 pts 1.0
EOF
cat >> in.$name
cat >> in.$name <<'EOF'
fix		grav all gravity 9.81 vector 0 0 -1
fix		integr all nve/sphere
thermo_style	custom step atoms ke
thermo		1000
thermo_modify	lost ignore norm no
EOF
prev=0
for s in 1 2 5000 10001 10002 12000 20001 25000 30000 34000 40000; do
  d=$((s-prev))
  if [ $prev = 0 ]; then echo "run $d" >> in.$name; else echo "run $d pre no" >> in.$name; fi
  echo "write_dump all custom dump.F$s id x y z vx vy vz omegax omegay omegaz modify sort id" >> in.$name
  prev=$s
done
}
gen stream_ol <<'EOF'
fix		ins all insert/stream seed 32452843 distributiontemplate pdd nparticles 200 particlerate 1000 overlapcheck yes vel uniform 0. 0. -1. 0.05 0.05 0.05 insertion_face face extrude_length 0.05
EOF
gen stream_noch <<'EOF'
fix		ins all insert/stream seed 32452843 distributiontemplate pdd nparticles 100 particlerate 500 overlapcheck no vel constant 0.05 0. -1. insertion_face face extrude_length 0.05
EOF
FACESTYLE=mesh/surface/planar gen stream_allin <<'EOF'
fix		ins all insert/stream seed 32452843 distributiontemplate pdd nparticles 200 particlerate 1000 overlapcheck yes all_in yes vel uniform 0. 0. -1. 0.05 0.05 0.05 insertion_face face extrude_length 0.05
EOF
